with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('ee282821-bc97-486d-b650-db80fb45616d'::uuid,ARRAY['Noun 1 並びに Noun 2']::text[],ARRAY['Use this construction to express A conjunction used to combine two nouns or noun phrases.. A conjunction used to combine two nouns or noun phrases.']::text[],ARRAY['【Related Expression: と; 及び】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"国連総会には首相並びに外務大臣が出席した。","japanese_furigana":"国連総会には首相並びに外務大臣が出席した。","english":"The prime minister and the foreign minister attended the U.N. General Assembly."},{"japanese":"県並びに県内各市町村では、地域イントラネット構築して、行政や福祉情報の円滑な提供に努めている。","japanese_furigana":"県並びに県内各市町村では、地域イントラネット構築して、行政や福祉情報の円滑な提供に努めている。","english":"The prefecture and its municipalities have constructed local intranets, and are working to provide administrative and welfare information smoothly to their residents."}]'::jsonb),
    ('747c5e0c-8c50-4e67-b3bd-8b9493c809f7'::uuid,ARRAY['(i) Noun 並み だ']::text[],ARRAY['Use this construction to express A noun sufﬁx that adds the meaning “to match”.. A noun sufﬁx that adds the meaning “to match”.']::text[],ARRAY['【Related Expression: と同じくらい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"マイクさんのゴルフはプロ並みだ。","japanese_furigana":"マイクさんのゴルフはプロ並みだ。","english":"Mike''s golf skills are about the same level as a pro''s."},{"japanese":"吉田さんは植物については専門家並みの知識を持っている。","japanese_furigana":"吉田さんは植物については専門家並みの知識を持っている。","english":"Regarding plants, Ms. Yoshida has as much knowledge as a specialist."}]'::jsonb),
    ('780b9be1-9732-49b1-adb0-876ce87e60d0'::uuid,ARRAY['(i) { 今更 +Wh-word/Wh-word+ 今更 } +Predicate (Affirmative)(か)。']::text[],ARRAY['Use this construction to express An adverb indicating that someone feels that it is too late to do something.. An adverb indicating that someone feels that it is too late to do something.']::text[],ARRAY['【Related Expression: 今になって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この話は二年も前に話し合ったじゃないか。なんで、今更同じ話を持ち出すんだ。","japanese_furigana":"この話は二年も前に話し合ったじゃないか。なんで、今更同じ話を持ち出すんだ。","english":"Didn''t we discuss this issue two years back? How come you are bringing it up after such a long time?"},{"japanese":"今更契約を解消するわけにはいかない。","japanese_furigana":"今更契約を解消するわけにはいかない。","english":"It is too late to cancel the contract."}]'::jsonb),
    ('69dae1f2-fc13-4f4f-8a7d-e7dfd0e01637'::uuid,ARRAY['(i) Noun の代わりに']::text[],ARRAY['Use this construction to express Something (including an action) replaces something else.. Something (including an action) replaces something else.']::text[],ARRAY['【Related Expression: けれど(も); しかし】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"先生のかわりに私が教えた・教えました。","japanese_furigana":"先生のかわりに私が教えた・教えました。","english":"I taught in place of my teacher."},{"japanese":"土曜日に仕事をするかわりに月曜日は休む・休みます。","japanese_furigana":"土曜日に仕事をするかわりに月曜日は休む・休みます。","english":"To make up for working on Saturdays, I take Mondays off."}]'::jsonb),
    ('45b0bef5-5698-45fa-98ef-cbc18bd9c4fb'::uuid,ARRAY['(i) Vinformal 以上 ( は )']::text[],ARRAY['Use this construction to express A conjunction indicating the speaker/writer''s feeling that there should be a very strong logical/natural connection between wht precedes the conjunction and what follows it.. A conjunction indicating the speaker/writer''s feeling that there should be a very strong logical/natural connection between wht precedes the conjunction and what follows it.']::text[],ARRAY['【Related Expression: 限り(は); からには】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本に来た以上（は）、日本語をしっかり勉強したい。","japanese_furigana":"日本に来た以上（は）、日本語をしっかり勉強したい。","english":"Since I came to Japan, I would like to study Japanese hard."},{"japanese":"学生である以上（は）、勉強すべきだ。","japanese_furigana":"学生である以上（は）、勉強すべきだ。","english":"So long as you are a student, you should study."}]'::jsonb),
    ('d1dd4f0a-0a2f-4d9a-ac34-0a0f11e61121'::uuid,ARRAY['(i) Noun 以外 (のNoun)']::text[],ARRAY['Use this construction to express A dependent noun which means "something/someone other than".. A dependent noun which means "something/someone other than".']::text[],ARRAY['【Related Expression: ほか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山田さん以外の人はみんなそのことを知っています。","japanese_furigana":"山田さん以外の人はみんなそのことを知っています。","english":"Everybody except Yamada knows it."},{"japanese":"日本語以外に何か外国語が話せますか。","japanese_furigana":"日本語以外に何か外国語が話せますか。","english":"Can you speak any foreign language besides Japanese?"}]'::jsonb),
    ('ee4cbe5f-10b7-4f38-9c2d-08c705a363d3'::uuid,ARRAY['(i) Noun 以来 Where Noun indicates an event or a specific time']::text[],ARRAY['Use this construction to express An adverb meaning “since”. An adverb meaning “since”']::text[],ARRAY['【Related Expression: から; いこう; いご】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"大統領の支持率が就任以来最低となった。","japanese_furigana":"大統領の支持率が就任以来最低となった。","english":"The president''s approval ratings have hit their lowest level since his presidency began."},{"japanese":"G社が、創業以来初めてホームページのデザインを変更した。","japanese_furigana":"G社が、創業以来初めてホームページのデザインを変更した。","english":"Company G changed the design of its homepage for the ﬁrst time since it opened for business."}]'::jsonb),
    ('21f1efcb-705c-4223-afac-571d86d18ab4'::uuid,ARRAY['(i) 仮に Sinformalと{したら/すれば}']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker’s/writer’s tentative supposition.. An adverb that indicates the speaker’s/writer’s tentative supposition.']::text[],ARRAY['【Related Expression: もし(も)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"仮に一億円｛もらう/もらった｝と｛したら/すれば｝何に使いますか。","japanese_furigana":"仮に一億円｛もらう/もらった｝と｛したら/すれば｝何に使いますか。","english":"Supposing you received 100 million yen, what would you use it for?"},{"japanese":"仮に月収が30万円｛ある/あった｝として、どのようなアパートを借りることができるだろうか。","japanese_furigana":"仮に月収が30万円｛ある/あった｝として、どのようなアパートを借りることができるだろうか。","english":"Supposing that I had an income of 300,000 yen, I wonder what kind of an apartment I could rent."}]'::jsonb),
    ('29ce5dbe-e7ea-4482-b504-4b7a837b2d90'::uuid,ARRAY['Sentence1。 但し 、Sentence。']::text[],ARRAY['Use this construction to express A conjunction indicating that there is a condition, restriction, proviso, etc., to the preceding statement.. A conjunction indicating that there is a condition, restriction, proviso, etc., to the preceding statement.']::text[],ARRAY['【Related Expression: ただ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この部屋にある雑誌や本はどれを見てもいいです。但し、部屋からは持ち出さないで下さい。","japanese_furigana":"この部屋にある雑誌や本はどれを見てもいいです。但し、部屋からは持ち出さないで下さい。","english":"You may look at any of the magazines or books in this room. However, please do not take them out of the room."},{"japanese":"当館の開館時間は午前9時から午後６時まで。但し、特別行事がある場合はこの限りではない。","japanese_furigana":"当館の開館時間は午前9時から午後６時まで。但し、特別行事がある場合はこの限りではない。","english":"This hall is open from 9 a.m. to 6 pm. However, for special events, the hall is not limited to these hours."}]'::jsonb),
    ('4bce700b-6756-43a3-ac0e-14e16db70862'::uuid,ARRAY['Canonical pattern: 何しろ']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker''s emotive feeling about some extreme state of affairs.. An adverb that indicates the speaker''s emotive feeling about some extreme state of affairs.']::text[],ARRAY['【Related Expression: とにかく】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"うちの父は頑固なんだ。何しろ一度言い出したら絶対に引き下がらないんだから。","japanese_furigana":"うちの父は頑固なんだ。何しろ一度言い出したら絶対に引き下がらないんだから。","english":"My father is obstinate. As a matter of fact, once he says he will do something, he never changes his mind."},{"japanese":"Ａ：この大学の教育はいいらしいね。Ｂ：うん、何しろ学生六人に先生一人だからね。","japanese_furigana":"Ａ：この大学の教育はいいらしいね。Ｂ：うん、何しろ学生六人に先生一人だからね。","english":"A: I heard that education at this college is good. B: Yeah, you may be surprised, but the student-instructor ratio is 6 to 1."}]'::jsonb),
    ('b2a43ef4-b473-44e0-bc0e-94d0e2917760'::uuid,ARRAY['Canonical pattern: 何とか']::text[],ARRAY['Use this construction to express An adverb expressing that someone somehow does something, or something somehow occurs.. An adverb expressing that someone somehow does something, or something somehow occurs.']::text[],ARRAY['【Related Expression: どうにか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"我々は今の日本の政治状況を何とか変えようと努力しています。","japanese_furigana":"我々は今の日本の政治状況を何とか変えようと努力しています。","english":"We are making an effort to change the current Japanese political situation somehow."},{"japanese":"一見無理なことも、やってみれば何とか形になる。","japanese_furigana":"一見無理なことも、やってみれば何とか形になる。","english":"Something which appears to be impossible to do can take shape in one way or another, if you try."}]'::jsonb),
    ('36d4032e-d88b-419b-a241-864ba6ec1d94'::uuid,ARRAY['Canonical pattern: 分かる']::text[],ARRAY['Use this construction to express Can figure out (spontaneously) various facts –such as content, nature, value, meaning, cause, reason, result– about something whose existence is presupposed.. Can figure out (spontaneously) various facts –such as content, nature, value, meaning, cause, reason, result– about something whose existence is presupposed.']::text[],ARRAY['【Related Expression: 知る】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私（に）はこの言葉が分からない・分かりません。","japanese_furigana":"私（に）はこの言葉が分からない・分かりません。","english":"To me this word is not comprehensible. / I don’t understand this word."},{"japanese":"私にはこの映画の意味が分からない。","japanese_furigana":"私にはこの映画の意味が分からない。","english":"I don''t understand the meaning of this movie."}]'::jsonb),
    ('b6a270f8-2d50-450d-a481-984e08107b69'::uuid,ARRAY['(i) Noun 1 、Noun 2 、(…、) 加えて Noun']::text[],ARRAY['Use this construction to express A conjunction that means “in addition to what has just been mentioned”.. A conjunction that means “in addition to what has just been mentioned”.']::text[],ARRAY['【Related Expression: だけでなく~(も); ばかりでなく~(も); その上(に); 且つ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この冬のアメリカ東部は雪、雨、加えて強風の被害が大きかった。","japanese_furigana":"この冬のアメリカ東部は雪、雨、加えて強風の被害が大きかった。","english":"This winter the East Coast of the U.S. suffered terribly from snow, rain and, in addition, strong winds."},{"japanese":"この辺は物価が安い。（それに）加えて自然環境もすばらしい。","japanese_furigana":"この辺は物価が安い。（それに）加えて自然環境もすばらしい。","english":"Things are inexpensive in this neighbourhood. What''s more, the natural environment is amazing."}]'::jsonb),
    ('4f3cdfaa-a773-499d-91e4-acced1eb018d'::uuid,ARRAY['(i) 単に NPだ']::text[],ARRAY['Use this construction to express An adverb that means “simply”. An adverb that means “simply”']::text[],ARRAY['【Related Expression: ただ; に過ぎない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは単に文化の違いの問題だ。","japanese_furigana":"これは単に文化の違いの問題だ。","english":"This is simply a matter/problem of cultural differences."},{"japanese":"この車は単にボディーのデザインを変えただけだ。","japanese_furigana":"この車は単にボディーのデザインを変えただけだ。","english":"They did nothing more to this car than change the body design."}]'::jsonb),
    ('61b921ec-619e-4237-93ed-1bfbf9a73ab7'::uuid,ARRAY['(i) {V/Adjectiveい}Informal nonpast 反面']::text[],ARRAY['Use this construction to express A conjunction used to contrast the positive and negative sides of something/someone.. A conjunction used to contrast the positive and negative sides of something/someone.']::text[],ARRAY['【Related Expression: に対して; に反して; 一方(で)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"携帯電話は便利な反面、わずらわしいこともある。","japanese_furigana":"携帯電話は便利な反面、わずらわしいこともある。","english":"While cell phones are convenient, they are also sometimes annoying."},{"japanese":"この国は個人の意思が尊重される反面、グループとしてのまとまりが弱い。","japanese_furigana":"この国は個人の意思が尊重される反面、グループとしてのまとまりが弱い。","english":"In this society, while the individual''s will is respected, group unity is weak."}]'::jsonb),
    ('27528d89-432a-41cb-8aaf-ce00879fa58c'::uuid,ARRAY['Noun 同士']::text[],ARRAY['Use this construction to express A sufﬁx that adds the meaning of “the same things/people”.. A sufﬁx that adds the meaning of “the same things/people”.']::text[],ARRAY['【Related Expression: と; 一緒に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"磁石のN極（またはS極）同士は反発する。","japanese_furigana":"磁石のN極（またはS極）同士は反発する。","english":"North poles (or south poles) of magnets repel each other."},{"japanese":"高校時代の友達同士で海外旅行に行くことになった。","japanese_furigana":"高校時代の友達同士で海外旅行に行くことになった。","english":"We’ve decided that we high school friends will travel abroad together."}]'::jsonb),
    ('6a864239-e6fa-4fe6-a700-39bac89a4a58'::uuid,ARRAY['Adjective い stem くて堪らない']::text[],ARRAY['Use this construction to express The speaker or whomever he empathises with cannot cope with a situation expressed by the て phrase.. The speaker or whomever he empathises with cannot cope with a situation expressed by the て phrase.']::text[],ARRAY['【Related Expression: しかがない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今日は暑くて堪らない・堪りません。","japanese_furigana":"今日は暑くて堪らない・堪りません。","english":"It is unbearably hot today."},{"japanese":"数学が嫌いで堪らない・堪りません。","japanese_furigana":"数学が嫌いで堪らない・堪りません。","english":"I really hate math."}]'::jsonb),
    ('8e53778c-59ea-4213-8b75-89e01eef3ec8'::uuid,ARRAY['Canonical pattern: 多い']::text[],ARRAY['Use this construction to express (of quantity or number) a lot. (of quantity or number) a lot']::text[],ARRAY['【Related Expression: 大勢; たくさん】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本（に）は大学が多い・多いです。","japanese_furigana":"日本（に）は大学が多い・多いです。","english":"In Japan universities are many."},{"japanese":"京都（に）はお寺が多いです。","japanese_furigana":"京都（に）はお寺が多いです。","english":"There are many temples in Kyoto."}]'::jsonb),
    ('50cb168e-4a80-4879-8eea-bd418b09694a'::uuid,ARRAY['Canonical pattern: 好きだ']::text[],ARRAY['Use this construction to express Something or someone is what someone likes.. Something or someone is what someone likes.']::text[],ARRAY['【Antonym Expression: 嫌いだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はステーキが好きだ・好きです。","japanese_furigana":"私はステーキが好きだ・好きです。","english":"I like steak."},{"japanese":"僕は野球が好きだ。","japanese_furigana":"僕は野球が好きだ。","english":"I like baseball."}]'::jsonb),
    ('2525b496-a5e2-4d03-b658-8c0e9ee425b2'::uuid,ARRAY['(i) Noun 如何']::text[],ARRAY['Use this construction to express A classic form of the adverb どのように “in what way”.. A classic form of the adverb どのように “in what way”.']::text[],ARRAY['【Related Expression: 次第; による/よって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私がこの会社に採用されるかどうかは、面接の結果如何だ。","japanese_furigana":"私がこの会社に採用されるかどうかは、面接の結果如何だ。","english":"Whether or not I''ll be hired by this company depends on the results of my interview."},{"japanese":"今年の新車の売れ行き如何｛で/によって｝この会社の将来が決まりそうだ。","japanese_furigana":"今年の新車の売れ行き如何｛で/によって｝この会社の将来が決まりそうだ。","english":"It looks like this company''s future will be determined by this year''s new car sales (literally: how new car sales are this year)."}]'::jsonb),
    ('7ed1dd32-e416-4f36-9bbe-fae20162f7bd'::uuid,ARRAY['Canonical pattern: 嫌いだ']::text[],ARRAY['Use this construction to express Something or someone is what someone does not like.. Something or someone is what someone does not like.']::text[],ARRAY['【Antonym Expression: 好きだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はチーズが嫌いだ・嫌いです。","japanese_furigana":"私はチーズが嫌いだ・嫌いです。","english":"I don''t like cheese."},{"japanese":"僕は冬が嫌いだ。","japanese_furigana":"僕は冬が嫌いだ。","english":"I dislike winter."}]'::jsonb),
    ('9eebc735-d7ef-49bd-91c4-214169cb7ca4'::uuid,ARRAY['Canonical pattern: 少ない']::text[],ARRAY['Use this construction to express Small in number of quantity.. Small in number of quantity.']::text[],ARRAY['【Related Expression: わずか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この町はいいレストランが少ない・少ないです。","japanese_furigana":"この町はいいレストランが少ない・少ないです。","english":"In this town good restaurants are few."},{"japanese":"この大学は女子学生が少ないです。","japanese_furigana":"この大学は女子学生が少ないです。","english":"The number of female students at this college is small."}]'::jsonb),
    ('481da469-7f24-404a-8753-1a19ed5d0c1c'::uuid,ARRAY['(i) 必ずしも {Vinformal/Adjectiveい} とは {限ら /言え/思わ}ない']::text[],ARRAY['Use this construction to express An adverb that indicates that the proposition expressed in the sentence is not always true.. An adverb that indicates that the proposition expressed in the sentence is not always true.']::text[],ARRAY['【Related Expression: いつもは~ない; みんなは~ない; 全ては~ない; 全部は~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"頭のいい人が、必ずしも成功するとは限らない。","japanese_furigana":"頭のいい人が、必ずしも成功するとは限らない。","english":"A bright person does not always succeed."},{"japanese":"高い料理が必ずしも美味しいわけではない。","japanese_furigana":"高い料理が必ずしも美味しいわけではない。","english":"Expensive dishes are not always delicious."}]'::jsonb),
    ('a164da07-a5fb-49cd-899b-b3bea2d52cb1'::uuid,ARRAY['Canonical pattern: 思えば']::text[],ARRAY['Use this construction to express An adverb that indicates feelings of nostalgia or regret when recollecting one’s past experiences.. An adverb that indicates feelings of nostalgia or regret when recollecting one’s past experiences.']::text[],ARRAY['The core sense is An adverb that indicates feelings of nostalgia or regret when recollecting one’s past experiences.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"思えば、大学時代はとても楽しかった。","japanese_furigana":"思えば、大学時代はとても楽しかった。","english":"When I come to think of it, I had a great time when I was in college."},{"japanese":"思えば、あの頃私は彼と政治問題について毎日のように議論したものだ。","japanese_furigana":"思えば、あの頃私は彼と政治問題について毎日のように議論したものだ。","english":"When I think back, I discussed political issues with him almost every day."}]'::jsonb),
    ('aed3a6ac-1ae0-4b11-8a9c-7fbc3a7ef4ba'::uuid,ARRAY['(i) {V/Adjective い}informal ように 思われる']::text[],ARRAY['Use this construction to express A verb that indicates what the speaker/writer feels spontaneously or his/her hesitation about asserting himself/herself.. A verb that indicates what the speaker/writer feels spontaneously or his/her hesitation about asserting himself/herself.']::text[],ARRAY['The core sense is A verb that indicates what the speaker/writer feels spontaneously or his/her hesitation about asserting himself/herself.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"来年の景気は今年よりもいいように思われる。","japanese_furigana":"来年の景気は今年よりもいいように思われる。","english":"It seems that the business conditions of the coming year will be better than those of this year."},{"japanese":"この病気の治療は約一か月かかると思われる。","japanese_furigana":"この病気の治療は約一か月かかると思われる。","english":"It appears that the treatment of this disease will take approximately one month."}]'::jsonb),
    ('6df780ff-b06c-4a28-8b4a-f2752067e63a'::uuid,ARRAY['(i) Nounの 折 ( に )']::text[],ARRAY['Use this construction to express A noun indicating special/uncommon and primarily desirable occasions which someone takes advantage of, or where someone is expected to do something or where something desirable takes place.. A noun indicating special/uncommon and primarily desirable occasions which someone takes advantage of, or where someone is expected to do something or where something desirable takes place.']::text[],ARRAY['【Related Expression: 時; さい; (せつ)に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"上京の折(に)はぜひお立ち寄り下さい。","japanese_furigana":"上京の折(に)はぜひお立ち寄り下さい。","english":"When you come up to Tokyo, please be sure to stop by."},{"japanese":"この前日本に帰った折(に)高校時代の友達に会った。","japanese_furigana":"この前日本に帰った折(に)高校時代の友達に会った。","english":"When I returned to Japan last time, I met with my high school friends."}]'::jsonb),
    ('25e8992d-8b48-4179-817f-d8942f7bc7ee'::uuid,ARRAY['(i) {Noun(の)/Adjectiveなstem(な)} 故 ( に )']::text[],ARRAY['Use this construction to express A conjunction that presents a reason or a cause.. A conjunction that presents a reason or a cause.']::text[],ARRAY['【Related Expression: (為)に; から; ので; だから; 従って】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女はその美貌(の)故(に)、悩みも多い。","japanese_furigana":"彼女はその美貌(の)故(に)、悩みも多い。","english":"Because of her good looks, she also has many things to worry about."},{"japanese":"結果にこだわりすぎる(が)故(に)、小さなことに心を奪われることになる。","japanese_furigana":"結果にこだわりすぎる(が)故(に)、小さなことに心を奪われることになる。","english":"Because you want the end result to be perfect, you end up being distracted by little things."}]'::jsonb),
    ('1b93cdf3-ade3-4d90-a15f-3470e0c8f48b'::uuid,ARRAY['(i) 更に Adjective(い/な)']::text[],ARRAY['Use this construction to express An adverb/conjunction that represents the idea of “additionally” or “further”.. An adverb/conjunction that represents the idea of “additionally” or “further”.']::text[],ARRAY['【Related Expression: 一緒; なお; もっと; より; あと; もう; その上; ひいては; 且つ; なお】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"更に大きいハリケーンがテキサス南部を襲った。","japanese_furigana":"更に大きいハリケーンがテキサス南部を襲った。","english":"An even larger hurricane struck South Texas."},{"japanese":"前の翻訳も難しかったが今度のは更に難しい。","japanese_furigana":"前の翻訳も難しかったが今度のは更に難しい。","english":"The last translation (job) was difficult, but this one is even harder."}]'::jsonb),
    ('7f0192bf-77a5-4490-9758-2d2436dc03be'::uuid,ARRAY['(i) Nounの 末 ( に )']::text[],ARRAY['Use this construction to express A noun that indicates the end of a period or the time after long, hard mental or physical work.. A noun that indicates the end of a period or the time after long, hard mental or physical work.']::text[],ARRAY['【Related Expression: あと(で); のち(に); あげく(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"さんざん迷った末に、友達の結婚祝いはコーヒーカップのセットを贈ることにした。","japanese_furigana":"さんざん迷った末に、友達の結婚祝いはコーヒーカップのセットを贈ることにした。","english":"After much hesitation, I decided to give my friends a set of coffee cups as a wedding present."},{"japanese":"試行錯誤の末(に)、やっと車に使える燃料電池ができた。","japanese_furigana":"試行錯誤の末(に)、やっと車に使える燃料電池ができた。","english":"After much trial and error, we ﬁnally made a fuel cell battery that can be used in cars."}]'::jsonb),
    ('3a225932-df04-4a00-9d99-2f9b082fafa7'::uuid,ARRAY['(i) Noun (duration) 来']::text[],ARRAY['Use this construction to express During a certain amount of time (something has continued up until the moment of speech or something has never been like the current state).. During a certain amount of time (something has continued up until the moment of speech or something has never been like the current state).']::text[],ARRAY['【Related Expression: ぶり; 以来; かん; 前から】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"トムは二十年来日本語の勉強を続けている。","japanese_furigana":"トムは二十年来日本語の勉強を続けている。","english":"Tom has been studying Japanese for the past 20 years."},{"japanese":"今年の冬は五十年来の寒さだ。","japanese_furigana":"今年の冬は五十年来の寒さだ。","english":"This winter is the coldest one in 50 years."}]'::jsonb),
    ('48b89fe0-d287-4f7d-abe9-4b3cc07c9325'::uuid,ARRAY['(i) Vます 次第']::text[],ARRAY['Use this construction to express A conjunction/noun to express that an action indicated by a preceding verb or an action implied by a preceding noun is a prerequisite for another action.. A conjunction/noun to express that an action indicated by a preceding verb or an action implied by a preceding noun is a prerequisite for another action.']::text[],ARRAY['【Related Expression: による; たらすぐ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"大阪に着き次第、お電話を差し上げます。","japanese_furigana":"大阪に着き次第、お電話を差し上げます。","english":"As soon as I get to Osaka, I will call you."},{"japanese":"原稿は完成次第お送り致します。","japanese_furigana":"原稿は完成次第お送り致します。","english":"I will send my manuscripts as soon as they are completed."}]'::jsonb),
    ('140f2cce-0c4f-4e06-bacf-f79c5fa05451'::uuid,ARRAY['Noun of time 毎']::text[],ARRAY['Use this construction to express A prefix which means ‘every (unit of time)’.. A prefix which means ‘every (unit of time)’.']::text[],ARRAY['【Related Expression: ごとに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は毎日一マイル泳ぐ・泳ぎます。","japanese_furigana":"私は毎日一マイル泳ぐ・泳ぎます。","english":"I swim one mile every day."},{"japanese":"弘は毎晩道子に電話しているそうだ。","japanese_furigana":"弘は毎晩道子に電話しているそうだ。","english":"I heard that Hiroshi calls Michiko every evening."}]'::jsonb),
    ('2f917c34-9614-4cd0-a27d-eccf6fc679a7'::uuid,ARRAY['(i) Number(+Counter)で 済む']::text[],ARRAY['Use this construction to express A verb that means “to be finished; to do (in the sense of being enough)”.. A verb that means “to be finished; to do (in the sense of being enough)”.']::text[],ARRAY['【Related Expression: 済ませる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ちょっと顔を見せるだけで済むと思う。","japanese_furigana":"ちょっと顔を見せるだけで済むと思う。","english":"I think just showing up for a while will be enough."},{"japanese":"面接は20分で済んだ。","japanese_furigana":"面接は20分で済んだ。","english":"The interview took only 20 minutes."}]'::jsonb),
    ('a01b413b-33ea-4a35-94bd-f7da7b5b6a93'::uuid,ARRAY['(i) {Demonstrative/Quantifier} 点 ( で )']::text[],ARRAY['Use this construction to express A noun which expresses the idea of "a point of argument; a point of evaluation; a point of view".. A noun which expresses the idea of "a point of argument; a point of evaluation; a point of view".']::text[],ARRAY['【Related Expression: 面】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はそういう点でまだ大人とは言えない。","japanese_furigana":"彼はそういう点でまだ大人とは言えない。","english":"He is not (literally: cannot be called) an adult in that respect."},{"japanese":"使いやすさの点ではこの辞書はネルソンの漢英辞典に及ばない。","japanese_furigana":"使いやすさの点ではこの辞書はネルソンの漢英辞典に及ばない。","english":"This dictionary is no match for Nelson''s Japanese-English Character Dictionary in terms of ease of use."}]'::jsonb),
    ('0659d80a-69a6-4eb5-ae0d-e4a782083eb3'::uuid,ARRAY['(i) {V/Adjective い} informal ために']::text[],ARRAY['Use this construction to express A noun that indicates a benefit, a purpose, a reason or a cause.. A noun that indicates a benefit, a purpose, a reason or a cause.']::text[],ARRAY['【Related Expression: から3; に5; ので; のに2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"学生は試験のために勉強する・勉強します。","japanese_furigana":"学生は試験のために勉強する・勉強します。","english":"Students study in preparation for exams. / Students study because there are exams."},{"japanese":"私は日本のことを知るため（に）日本へ行く・行きます。","japanese_furigana":"私は日本のことを知るため（に）日本へ行く・行きます。","english":"I''ll go to Japan (in order) to learn about Japan."}]'::jsonb),
    ('fb3568a1-9f26-4024-9716-64e7b04d0c17'::uuid,ARRAY['(i) Nounの 由']::text[],ARRAY['Use this construction to express A dependent noun that marks the content of what the writer has learned.. A dependent noun that marks the content of what the writer has learned.']::text[],ARRAY['【Related Expression: とのこと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この度は本社営業部長にご栄転の由、誠におめでとう存じます。","japanese_furigana":"この度は本社営業部長にご栄転の由、誠におめでとう存じます。","english":"I heard of your promotion this time to manager of the headquarters'' sales department. Please accept my sincere congratulations."},{"japanese":"地球環境保護の国際会議が来年当市で開催される由(である)。","japanese_furigana":"地球環境保護の国際会議が来年当市で開催される由(である)。","english":"It is said that an international conference on global environmental protection will be held in this city next year."}]'::jsonb),
    ('fc274c5c-cade-49b1-b7f2-f2562fd383e0'::uuid,ARRAY['(i) Vinformal 甲斐 が{ある/ない}']::text[],ARRAY['Use this construction to express A dependent noun that means something is worth someone’s effort.. A dependent noun that means something is worth someone’s effort.']::text[],ARRAY['The core sense is A dependent noun that means something is worth someone’s effort.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"日本語をよく勉強したかいがあって、日本語関係の会社に就職することができた。","japanese_furigana":"日本語をよく勉強したかいがあって、日本語関係の会社に就職することができた。","english":"It was worth studying Japanese hard because (literally: and) I was able to get a Japan-related job."},{"japanese":"社員一同の努力のかいがあって一時低調だった会社も上向きになった。","japanese_furigana":"社員一同の努力のかいがあって一時低調だった会社も上向きになった。","english":"The combined efforts of the company employees paid off, and the company, which had been in a slump for a while, started improving."}]'::jsonb),
    ('024d19e9-da37-4695-9fc4-163d1036aeb8'::uuid,ARRAY['Canonical pattern: 知る']::text[],ARRAY['Use this construction to express Someone gets information from some outside source.. Someone gets information from some outside source.']::text[],ARRAY['【Related Expression: 分かる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:日本のことを知っていますか。 B:はい、知っています。/いいえ、知りません。","japanese_furigana":"A:日本のことを知っていますか。 B:はい、知っています。/いいえ、知りません。","english":"A: Do you know about Japan? B: Yes, I do. / No, I don''t."},{"japanese":"木下さんを知っていますか。","japanese_furigana":"木下さんを知っていますか。","english":"Do you know Mr. Kinoshita?"}]'::jsonb),
    ('4be29420-bdc9-48c0-879f-f93d9c3c87e4'::uuid,ARRAY['(i) Noun の結果']::text[],ARRAY['Use this construction to express A noun which expresses the idea "as a result of".. A noun which expresses the idea "as a result of".']::text[],ARRAY['The core sense is A noun which expresses the idea "as a result of".; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"投票の結果、その提案は反対多数で否決された。","japanese_furigana":"投票の結果、その提案は反対多数で否決された。","english":"As a result of the vote, the proposal was rejected by the majority''s opposition."},{"japanese":"妻と相談した結果、家を買うことにした。","japanese_furigana":"妻と相談した結果、家を買うことにした。","english":"After my wife and I discussed it, we decided to buy a house."}]'::jsonb),
    ('537092c8-76c2-43bd-9932-7f0fa8b80130'::uuid,ARRAY['Canonical pattern: 結構']::text[],ARRAY['Use this construction to express An adverb that indicates that something exceeds the speaker''s and/or hearer''s expectation to a considerable degree.. An adverb that indicates that something exceeds the speaker''s and/or hearer''s expectation to a considerable degree.']::text[],ARRAY['【Related Expression: 案外; いがいと; 割合】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ここの寿司は、結構美味しいね。","japanese_furigana":"ここの寿司は、結構美味しいね。","english":"The sushi in this place is quite good, isn''t it?"},{"japanese":"この車は古いんだけど、結構よく走りますよ。","japanese_furigana":"この車は古いんだけど、結構よく走りますよ。","english":"This car is old, but it runs quite well, you know."}]'::jsonb),
    ('316ba829-4271-480f-802f-6eb5f9cb22d7'::uuid,ARRAY['Canonical pattern: 聞こえる']::text[],ARRAY['Use this construction to express Something is passively and spontaneously audiable.. Something is passively and spontaneously audiable.']::text[],ARRAY['【Related Expression: 聞ける】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私（に）は鶯の声がよく聞こえる・聞こえます。","japanese_furigana":"私（に）は鶯の声がよく聞こえる・聞こえます。","english":"To me the cries of a nightingale are clearly audible. / I can clearly hear the cries of a nightingale."},{"japanese":"その音は小さ過ぎて聞こえない。","japanese_furigana":"その音は小さ過ぎて聞こえない。","english":"That sound is too weak and is not audible."}]'::jsonb),
    ('24dee30c-315e-4986-88a4-70aa79e47089'::uuid,ARRAY['(i) NounPhrase 自体']::text[],ARRAY['Use this construction to express A dependent noun that is used to emphasize the referent of the preceding noun.. A dependent noun that is used to emphasize the referent of the preceding noun.']::text[],ARRAY['【Related Expression: 自身; そのもの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"インターネット自体は情報の通路であって、内容は持たない。","japanese_furigana":"インターネット自体は情報の通路であって、内容は持たない。","english":"The Internet is a path for information and does not contain any content itself."},{"japanese":"私にとってはこの試合に出られること自体が光栄なことです。","japanese_furigana":"私にとってはこの試合に出られること自体が光栄なことです。","english":"For me, being able to participate in this match in and of itself is an honour."}]'::jsonb),
    ('f37d1af4-4fb1-4320-b73f-c44ca51fee19'::uuid,ARRAY['Canonical pattern: 自分（共感視点）']::text[],ARRAY['Use this construction to express A reflexive pronoun that refers (back) to a human subject with whom the speaker is empathising.. A reflexive pronoun that refers (back) to a human subject with whom the speaker is empathising.']::text[],ARRAY['【Related Expression: 自分2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"土田は幸子が自分を愛していることを知らなかった・知りませんでした。","japanese_furigana":"土田は幸子が自分を愛していることを知らなかった・知りませんでした。","english":"Tsuchida didn''t know that Sachiko loved him (literally: himself)."},{"japanese":"1:ゆかりは歩きながら考えていた。 2:健一は自分が本当に好きなんだろうか。","japanese_furigana":"1:ゆかりは歩きながら考えていた。 2:健一は自分が本当に好きなんだろうか。","english":"1: Yukari was walking while thinking. 2: Does Kenichi really love me (literally: myself)?"}]'::jsonb),
    ('00fafc0f-33c7-42d2-9071-880d684c5f0d'::uuid,ARRAY['Canonical pattern: 自分（対比）']::text[],ARRAY['Use this construction to express A reflexive pronoun that refers (back) to a human subject, the referent of which is contrasted with someone else.. A reflexive pronoun that refers (back) to a human subject, the referent of which is contrasted with someone else.']::text[],ARRAY['【Related Expression: 自分1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本人は自分の国の文化をユニークだと思っている・います。","japanese_furigana":"日本人は自分の国の文化をユニークだと思っている・います。","english":"The Japanese think that their country''s culture is unique."},{"japanese":"メアリーは自分で何でもする・します。","japanese_furigana":"メアリーは自分で何でもする・します。","english":"Mary does everything by herself."}]'::jsonb),
    ('0fec0d16-aa16-4efa-b358-e25ae1445183'::uuid,ARRAY['Canonical pattern: 要る']::text[],ARRAY['Use this construction to express Someone, something needs something. Someone, something needs something']::text[],ARRAY['The core sense is Someone, something needs something; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"君達は英和辞典が要る・要ります。","japanese_furigana":"君達は英和辞典が要る・要ります。","english":"You need an English-Japanese dictionary."},{"japanese":"私は今お金が要る。","japanese_furigana":"私は今お金が要る。","english":"I need money now."}]'::jsonb),
    ('c6386e1f-7c54-4bba-8733-57001e003d10'::uuid,ARRAY['Canonical pattern: 見える']::text[],ARRAY['Use this construction to express Someone or something is passively/spontaneously visible.. Someone or something is passively/spontaneously visible.']::text[],ARRAY['【Related Expression: 見られる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私（に）は遠くの物がよく見える・見えます。","japanese_furigana":"私（に）は遠くの物がよく見える・見えます。","english":"To me distant objects are very visible."},{"japanese":"窓から（は）海が見える・見えます。","japanese_furigana":"窓から（は）海が見える・見えます。","english":"From the window the ocean is visible."}]'::jsonb),
    ('ee59f20f-43ee-4feb-ab47-74ef94f67a1c'::uuid,ARRAY['言わば Sentence。']::text[],ARRAY['Use this construction to express An adverb that means “if I were to say it some way (or a different way)”.. An adverb that means “if I were to say it some way (or a different way)”.']::text[],ARRAY['【Related Expression: 言ってみれば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この本は、言わば私のバイブルだ。","japanese_furigana":"この本は、言わば私のバイブルだ。","english":"This is, as it were, my Bible."},{"japanese":"この試験は言わばアメリカの大学に留学する際のTOEFLに当たる。","japanese_furigana":"この試験は言わばアメリカの大学に留学する際のTOEFLに当たる。","english":"This test is, so to speak, the equivalent of the TOEFL, which people take when they (want to) study at a university in the U.S."}]'::jsonb),
    ('ea9bb6cb-1dc7-41c8-8e5a-2adbc70b1d5d'::uuid,ARRAY['Canonical pattern: 逆に']::text[],ARRAY['Use this construction to express An adverb to introduce an event which takes place contrary to one''s expectation/intention, or an action or event which is converse to that stated in the preceding sentence or clause.. An adverb to introduce an event which takes place contrary to one''s expectation/intention, or an action or event which is converse to that stated in the preceding sentence or clause.']::text[],ARRAY['【Related Expression: かえって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"薬を飲んだら、逆に熱が出た。","japanese_furigana":"薬を飲んだら、逆に熱が出た。","english":"Contrary to expectations, when I took medicine, I got a fever."},{"japanese":"叱られると思ったのに、逆にほめられた。","japanese_furigana":"叱られると思ったのに、逆にほめられた。","english":"I expected to be scolded but, contrary to my expectation, I was praised."}]'::jsonb),
    ('26178254-75be-4a79-8188-a9854e515a6b'::uuid,ARRAY['(i) Vinformal past 途端 ( に )']::text[],ARRAY['Use this construction to express A noun/adverb which expresses the idea that ''something occurred the moment someone did something or something took place''.. A noun/adverb which expresses the idea that ''something occurred the moment someone did something or something took place''.']::text[],ARRAY['【Related Expression: と同時に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"先生の顔を見た途端（に）宿題があったことを思い出した。","japanese_furigana":"先生の顔を見た途端（に）宿題があったことを思い出した。","english":"The moment I saw my teacher, I remembered that there was a homework assignment."},{"japanese":"ドアを開けたら、途端にカレーの匂いがした。","japanese_furigana":"ドアを開けたら、途端にカレーの匂いがした。","english":"The moment I opened the door, I smelled curry."}]'::jsonb),
    ('4ad19909-6c29-4d06-825c-b178a2419682'::uuid,ARRAY['(i) Noun の通り(に)']::text[],ARRAY['Use this construction to express A dependent noun which expresses the idea that someone does something or something takes place in the same way as something else.. A dependent noun which expresses the idea that someone does something or something takes place in the same way as something else.']::text[],ARRAY['【Related Expression: ように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"説明書の通り（に）やったが、うまくいかなかった。","japanese_furigana":"説明書の通り（に）やったが、うまくいかなかった。","english":"I did it as the manual shows (literally: in the same way as the manual), but it didn''t work."},{"japanese":"私の言う通り（に）体を動かして下さい。","japanese_furigana":"私の言う通り（に）体を動かして下さい。","english":"Please move your body as I tell you to (literally: in the same way as I tell you)."}]'::jsonb),
    ('c6dd4e4e-fd9c-4937-a2f5-951c76eff013'::uuid,ARRAY['(i) Vinformal 際 ( に )']::text[],ARRAY['Use this construction to express On the special occasion of/when.. On the special occasion of/when.']::text[],ARRAY['【Related Expression: 場合; にあったって/あたり; おりに; 時に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"詳しいことは八月に上京する際に、お話し致します。","japanese_furigana":"詳しいことは八月に上京する際に、お話し致します。","english":"I will tell you the details when I come down to Tokyo in August."},{"japanese":"これは大学卒業の際に父が買ってくれたワープロです。","japanese_furigana":"これは大学卒業の際に父が買ってくれたワープロです。","english":"This is a word processor which my father bought me on the occasion of my college graduation."}]'::jsonb),
    ('1329e30b-6bbd-412a-82b5-f40a414b1517'::uuid,ARRAY['(i) おVます 願います']::text[],ARRAY['Use this construction to express A verb that expresses a polite request.. A verb that expresses a polite request.']::text[],ARRAY['【Related Expression: Verb て下さい; をVerb ます下さい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"初めに、これだけは必ずお読み願います。","japanese_furigana":"初めに、これだけは必ずお読み願います。","english":"Please be sure to read at least this (part) first."},{"japanese":"禁煙にご協力願います。","japanese_furigana":"禁煙にご協力願います。","english":"Thank you for not smoking (literally: Please cooperate with us in non-smoking)."}]'::jsonb),
    ('14a8f8e8-dd8c-4666-840a-11517e8586cb'::uuid,ARRAY['(i) {Noun/こんな/そんな/あんな/どんな} 風に Like {Noun/this/that/that ~ over there}, in what manner?']::text[],ARRAY['Use this construction to express With an appearance/style/tone/manner of ~.. With an appearance/style/tone/manner of ~.']::text[],ARRAY['【Related Expression: ように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私の家の庭は日本風に大きい石が置いてあります。","japanese_furigana":"私の家の庭は日本風に大きい石が置いてあります。","english":"The yard of my house has big rocks arranged in Japanese style."},{"japanese":"あんな風に勉強していたらいい成績は取れないだろう。","japanese_furigana":"あんな風に勉強していたらいい成績は取れないだろう。","english":"If he studies like that, he won''t get good grades."}]'::jsonb)
), invalid as (
  select grammar_id from enrichment where not public.repository_reference_examples_valid(examples_value)
)
select case when count(*)=0 then true else false end as payloads_valid from invalid;

with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('ee282821-bc97-486d-b650-db80fb45616d'::uuid,ARRAY['Noun 1 並びに Noun 2']::text[],ARRAY['Use this construction to express A conjunction used to combine two nouns or noun phrases.. A conjunction used to combine two nouns or noun phrases.']::text[],ARRAY['【Related Expression: と; 及び】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"国連総会には首相並びに外務大臣が出席した。","japanese_furigana":"国連総会には首相並びに外務大臣が出席した。","english":"The prime minister and the foreign minister attended the U.N. General Assembly."},{"japanese":"県並びに県内各市町村では、地域イントラネット構築して、行政や福祉情報の円滑な提供に努めている。","japanese_furigana":"県並びに県内各市町村では、地域イントラネット構築して、行政や福祉情報の円滑な提供に努めている。","english":"The prefecture and its municipalities have constructed local intranets, and are working to provide administrative and welfare information smoothly to their residents."}]'::jsonb),
    ('747c5e0c-8c50-4e67-b3bd-8b9493c809f7'::uuid,ARRAY['(i) Noun 並み だ']::text[],ARRAY['Use this construction to express A noun sufﬁx that adds the meaning “to match”.. A noun sufﬁx that adds the meaning “to match”.']::text[],ARRAY['【Related Expression: と同じくらい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"マイクさんのゴルフはプロ並みだ。","japanese_furigana":"マイクさんのゴルフはプロ並みだ。","english":"Mike''s golf skills are about the same level as a pro''s."},{"japanese":"吉田さんは植物については専門家並みの知識を持っている。","japanese_furigana":"吉田さんは植物については専門家並みの知識を持っている。","english":"Regarding plants, Ms. Yoshida has as much knowledge as a specialist."}]'::jsonb),
    ('780b9be1-9732-49b1-adb0-876ce87e60d0'::uuid,ARRAY['(i) { 今更 +Wh-word/Wh-word+ 今更 } +Predicate (Affirmative)(か)。']::text[],ARRAY['Use this construction to express An adverb indicating that someone feels that it is too late to do something.. An adverb indicating that someone feels that it is too late to do something.']::text[],ARRAY['【Related Expression: 今になって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この話は二年も前に話し合ったじゃないか。なんで、今更同じ話を持ち出すんだ。","japanese_furigana":"この話は二年も前に話し合ったじゃないか。なんで、今更同じ話を持ち出すんだ。","english":"Didn''t we discuss this issue two years back? How come you are bringing it up after such a long time?"},{"japanese":"今更契約を解消するわけにはいかない。","japanese_furigana":"今更契約を解消するわけにはいかない。","english":"It is too late to cancel the contract."}]'::jsonb),
    ('69dae1f2-fc13-4f4f-8a7d-e7dfd0e01637'::uuid,ARRAY['(i) Noun の代わりに']::text[],ARRAY['Use this construction to express Something (including an action) replaces something else.. Something (including an action) replaces something else.']::text[],ARRAY['【Related Expression: けれど(も); しかし】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"先生のかわりに私が教えた・教えました。","japanese_furigana":"先生のかわりに私が教えた・教えました。","english":"I taught in place of my teacher."},{"japanese":"土曜日に仕事をするかわりに月曜日は休む・休みます。","japanese_furigana":"土曜日に仕事をするかわりに月曜日は休む・休みます。","english":"To make up for working on Saturdays, I take Mondays off."}]'::jsonb),
    ('45b0bef5-5698-45fa-98ef-cbc18bd9c4fb'::uuid,ARRAY['(i) Vinformal 以上 ( は )']::text[],ARRAY['Use this construction to express A conjunction indicating the speaker/writer''s feeling that there should be a very strong logical/natural connection between wht precedes the conjunction and what follows it.. A conjunction indicating the speaker/writer''s feeling that there should be a very strong logical/natural connection between wht precedes the conjunction and what follows it.']::text[],ARRAY['【Related Expression: 限り(は); からには】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本に来た以上（は）、日本語をしっかり勉強したい。","japanese_furigana":"日本に来た以上（は）、日本語をしっかり勉強したい。","english":"Since I came to Japan, I would like to study Japanese hard."},{"japanese":"学生である以上（は）、勉強すべきだ。","japanese_furigana":"学生である以上（は）、勉強すべきだ。","english":"So long as you are a student, you should study."}]'::jsonb),
    ('d1dd4f0a-0a2f-4d9a-ac34-0a0f11e61121'::uuid,ARRAY['(i) Noun 以外 (のNoun)']::text[],ARRAY['Use this construction to express A dependent noun which means "something/someone other than".. A dependent noun which means "something/someone other than".']::text[],ARRAY['【Related Expression: ほか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山田さん以外の人はみんなそのことを知っています。","japanese_furigana":"山田さん以外の人はみんなそのことを知っています。","english":"Everybody except Yamada knows it."},{"japanese":"日本語以外に何か外国語が話せますか。","japanese_furigana":"日本語以外に何か外国語が話せますか。","english":"Can you speak any foreign language besides Japanese?"}]'::jsonb),
    ('ee4cbe5f-10b7-4f38-9c2d-08c705a363d3'::uuid,ARRAY['(i) Noun 以来 Where Noun indicates an event or a specific time']::text[],ARRAY['Use this construction to express An adverb meaning “since”. An adverb meaning “since”']::text[],ARRAY['【Related Expression: から; いこう; いご】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"大統領の支持率が就任以来最低となった。","japanese_furigana":"大統領の支持率が就任以来最低となった。","english":"The president''s approval ratings have hit their lowest level since his presidency began."},{"japanese":"G社が、創業以来初めてホームページのデザインを変更した。","japanese_furigana":"G社が、創業以来初めてホームページのデザインを変更した。","english":"Company G changed the design of its homepage for the ﬁrst time since it opened for business."}]'::jsonb),
    ('21f1efcb-705c-4223-afac-571d86d18ab4'::uuid,ARRAY['(i) 仮に Sinformalと{したら/すれば}']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker’s/writer’s tentative supposition.. An adverb that indicates the speaker’s/writer’s tentative supposition.']::text[],ARRAY['【Related Expression: もし(も)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"仮に一億円｛もらう/もらった｝と｛したら/すれば｝何に使いますか。","japanese_furigana":"仮に一億円｛もらう/もらった｝と｛したら/すれば｝何に使いますか。","english":"Supposing you received 100 million yen, what would you use it for?"},{"japanese":"仮に月収が30万円｛ある/あった｝として、どのようなアパートを借りることができるだろうか。","japanese_furigana":"仮に月収が30万円｛ある/あった｝として、どのようなアパートを借りることができるだろうか。","english":"Supposing that I had an income of 300,000 yen, I wonder what kind of an apartment I could rent."}]'::jsonb),
    ('29ce5dbe-e7ea-4482-b504-4b7a837b2d90'::uuid,ARRAY['Sentence1。 但し 、Sentence。']::text[],ARRAY['Use this construction to express A conjunction indicating that there is a condition, restriction, proviso, etc., to the preceding statement.. A conjunction indicating that there is a condition, restriction, proviso, etc., to the preceding statement.']::text[],ARRAY['【Related Expression: ただ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この部屋にある雑誌や本はどれを見てもいいです。但し、部屋からは持ち出さないで下さい。","japanese_furigana":"この部屋にある雑誌や本はどれを見てもいいです。但し、部屋からは持ち出さないで下さい。","english":"You may look at any of the magazines or books in this room. However, please do not take them out of the room."},{"japanese":"当館の開館時間は午前9時から午後６時まで。但し、特別行事がある場合はこの限りではない。","japanese_furigana":"当館の開館時間は午前9時から午後６時まで。但し、特別行事がある場合はこの限りではない。","english":"This hall is open from 9 a.m. to 6 pm. However, for special events, the hall is not limited to these hours."}]'::jsonb),
    ('4bce700b-6756-43a3-ac0e-14e16db70862'::uuid,ARRAY['Canonical pattern: 何しろ']::text[],ARRAY['Use this construction to express An adverb that indicates the speaker''s emotive feeling about some extreme state of affairs.. An adverb that indicates the speaker''s emotive feeling about some extreme state of affairs.']::text[],ARRAY['【Related Expression: とにかく】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"うちの父は頑固なんだ。何しろ一度言い出したら絶対に引き下がらないんだから。","japanese_furigana":"うちの父は頑固なんだ。何しろ一度言い出したら絶対に引き下がらないんだから。","english":"My father is obstinate. As a matter of fact, once he says he will do something, he never changes his mind."},{"japanese":"Ａ：この大学の教育はいいらしいね。Ｂ：うん、何しろ学生六人に先生一人だからね。","japanese_furigana":"Ａ：この大学の教育はいいらしいね。Ｂ：うん、何しろ学生六人に先生一人だからね。","english":"A: I heard that education at this college is good. B: Yeah, you may be surprised, but the student-instructor ratio is 6 to 1."}]'::jsonb),
    ('b2a43ef4-b473-44e0-bc0e-94d0e2917760'::uuid,ARRAY['Canonical pattern: 何とか']::text[],ARRAY['Use this construction to express An adverb expressing that someone somehow does something, or something somehow occurs.. An adverb expressing that someone somehow does something, or something somehow occurs.']::text[],ARRAY['【Related Expression: どうにか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"我々は今の日本の政治状況を何とか変えようと努力しています。","japanese_furigana":"我々は今の日本の政治状況を何とか変えようと努力しています。","english":"We are making an effort to change the current Japanese political situation somehow."},{"japanese":"一見無理なことも、やってみれば何とか形になる。","japanese_furigana":"一見無理なことも、やってみれば何とか形になる。","english":"Something which appears to be impossible to do can take shape in one way or another, if you try."}]'::jsonb),
    ('36d4032e-d88b-419b-a241-864ba6ec1d94'::uuid,ARRAY['Canonical pattern: 分かる']::text[],ARRAY['Use this construction to express Can figure out (spontaneously) various facts –such as content, nature, value, meaning, cause, reason, result– about something whose existence is presupposed.. Can figure out (spontaneously) various facts –such as content, nature, value, meaning, cause, reason, result– about something whose existence is presupposed.']::text[],ARRAY['【Related Expression: 知る】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私（に）はこの言葉が分からない・分かりません。","japanese_furigana":"私（に）はこの言葉が分からない・分かりません。","english":"To me this word is not comprehensible. / I don’t understand this word."},{"japanese":"私にはこの映画の意味が分からない。","japanese_furigana":"私にはこの映画の意味が分からない。","english":"I don''t understand the meaning of this movie."}]'::jsonb),
    ('b6a270f8-2d50-450d-a481-984e08107b69'::uuid,ARRAY['(i) Noun 1 、Noun 2 、(…、) 加えて Noun']::text[],ARRAY['Use this construction to express A conjunction that means “in addition to what has just been mentioned”.. A conjunction that means “in addition to what has just been mentioned”.']::text[],ARRAY['【Related Expression: だけでなく~(も); ばかりでなく~(も); その上(に); 且つ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この冬のアメリカ東部は雪、雨、加えて強風の被害が大きかった。","japanese_furigana":"この冬のアメリカ東部は雪、雨、加えて強風の被害が大きかった。","english":"This winter the East Coast of the U.S. suffered terribly from snow, rain and, in addition, strong winds."},{"japanese":"この辺は物価が安い。（それに）加えて自然環境もすばらしい。","japanese_furigana":"この辺は物価が安い。（それに）加えて自然環境もすばらしい。","english":"Things are inexpensive in this neighbourhood. What''s more, the natural environment is amazing."}]'::jsonb),
    ('4f3cdfaa-a773-499d-91e4-acced1eb018d'::uuid,ARRAY['(i) 単に NPだ']::text[],ARRAY['Use this construction to express An adverb that means “simply”. An adverb that means “simply”']::text[],ARRAY['【Related Expression: ただ; に過ぎない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは単に文化の違いの問題だ。","japanese_furigana":"これは単に文化の違いの問題だ。","english":"This is simply a matter/problem of cultural differences."},{"japanese":"この車は単にボディーのデザインを変えただけだ。","japanese_furigana":"この車は単にボディーのデザインを変えただけだ。","english":"They did nothing more to this car than change the body design."}]'::jsonb),
    ('61b921ec-619e-4237-93ed-1bfbf9a73ab7'::uuid,ARRAY['(i) {V/Adjectiveい}Informal nonpast 反面']::text[],ARRAY['Use this construction to express A conjunction used to contrast the positive and negative sides of something/someone.. A conjunction used to contrast the positive and negative sides of something/someone.']::text[],ARRAY['【Related Expression: に対して; に反して; 一方(で)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"携帯電話は便利な反面、わずらわしいこともある。","japanese_furigana":"携帯電話は便利な反面、わずらわしいこともある。","english":"While cell phones are convenient, they are also sometimes annoying."},{"japanese":"この国は個人の意思が尊重される反面、グループとしてのまとまりが弱い。","japanese_furigana":"この国は個人の意思が尊重される反面、グループとしてのまとまりが弱い。","english":"In this society, while the individual''s will is respected, group unity is weak."}]'::jsonb),
    ('27528d89-432a-41cb-8aaf-ce00879fa58c'::uuid,ARRAY['Noun 同士']::text[],ARRAY['Use this construction to express A sufﬁx that adds the meaning of “the same things/people”.. A sufﬁx that adds the meaning of “the same things/people”.']::text[],ARRAY['【Related Expression: と; 一緒に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"磁石のN極（またはS極）同士は反発する。","japanese_furigana":"磁石のN極（またはS極）同士は反発する。","english":"North poles (or south poles) of magnets repel each other."},{"japanese":"高校時代の友達同士で海外旅行に行くことになった。","japanese_furigana":"高校時代の友達同士で海外旅行に行くことになった。","english":"We’ve decided that we high school friends will travel abroad together."}]'::jsonb),
    ('6a864239-e6fa-4fe6-a700-39bac89a4a58'::uuid,ARRAY['Adjective い stem くて堪らない']::text[],ARRAY['Use this construction to express The speaker or whomever he empathises with cannot cope with a situation expressed by the て phrase.. The speaker or whomever he empathises with cannot cope with a situation expressed by the て phrase.']::text[],ARRAY['【Related Expression: しかがない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今日は暑くて堪らない・堪りません。","japanese_furigana":"今日は暑くて堪らない・堪りません。","english":"It is unbearably hot today."},{"japanese":"数学が嫌いで堪らない・堪りません。","japanese_furigana":"数学が嫌いで堪らない・堪りません。","english":"I really hate math."}]'::jsonb),
    ('8e53778c-59ea-4213-8b75-89e01eef3ec8'::uuid,ARRAY['Canonical pattern: 多い']::text[],ARRAY['Use this construction to express (of quantity or number) a lot. (of quantity or number) a lot']::text[],ARRAY['【Related Expression: 大勢; たくさん】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本（に）は大学が多い・多いです。","japanese_furigana":"日本（に）は大学が多い・多いです。","english":"In Japan universities are many."},{"japanese":"京都（に）はお寺が多いです。","japanese_furigana":"京都（に）はお寺が多いです。","english":"There are many temples in Kyoto."}]'::jsonb),
    ('50cb168e-4a80-4879-8eea-bd418b09694a'::uuid,ARRAY['Canonical pattern: 好きだ']::text[],ARRAY['Use this construction to express Something or someone is what someone likes.. Something or someone is what someone likes.']::text[],ARRAY['【Antonym Expression: 嫌いだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はステーキが好きだ・好きです。","japanese_furigana":"私はステーキが好きだ・好きです。","english":"I like steak."},{"japanese":"僕は野球が好きだ。","japanese_furigana":"僕は野球が好きだ。","english":"I like baseball."}]'::jsonb),
    ('2525b496-a5e2-4d03-b658-8c0e9ee425b2'::uuid,ARRAY['(i) Noun 如何']::text[],ARRAY['Use this construction to express A classic form of the adverb どのように “in what way”.. A classic form of the adverb どのように “in what way”.']::text[],ARRAY['【Related Expression: 次第; による/よって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私がこの会社に採用されるかどうかは、面接の結果如何だ。","japanese_furigana":"私がこの会社に採用されるかどうかは、面接の結果如何だ。","english":"Whether or not I''ll be hired by this company depends on the results of my interview."},{"japanese":"今年の新車の売れ行き如何｛で/によって｝この会社の将来が決まりそうだ。","japanese_furigana":"今年の新車の売れ行き如何｛で/によって｝この会社の将来が決まりそうだ。","english":"It looks like this company''s future will be determined by this year''s new car sales (literally: how new car sales are this year)."}]'::jsonb),
    ('7ed1dd32-e416-4f36-9bbe-fae20162f7bd'::uuid,ARRAY['Canonical pattern: 嫌いだ']::text[],ARRAY['Use this construction to express Something or someone is what someone does not like.. Something or someone is what someone does not like.']::text[],ARRAY['【Antonym Expression: 好きだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はチーズが嫌いだ・嫌いです。","japanese_furigana":"私はチーズが嫌いだ・嫌いです。","english":"I don''t like cheese."},{"japanese":"僕は冬が嫌いだ。","japanese_furigana":"僕は冬が嫌いだ。","english":"I dislike winter."}]'::jsonb),
    ('9eebc735-d7ef-49bd-91c4-214169cb7ca4'::uuid,ARRAY['Canonical pattern: 少ない']::text[],ARRAY['Use this construction to express Small in number of quantity.. Small in number of quantity.']::text[],ARRAY['【Related Expression: わずか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この町はいいレストランが少ない・少ないです。","japanese_furigana":"この町はいいレストランが少ない・少ないです。","english":"In this town good restaurants are few."},{"japanese":"この大学は女子学生が少ないです。","japanese_furigana":"この大学は女子学生が少ないです。","english":"The number of female students at this college is small."}]'::jsonb),
    ('481da469-7f24-404a-8753-1a19ed5d0c1c'::uuid,ARRAY['(i) 必ずしも {Vinformal/Adjectiveい} とは {限ら /言え/思わ}ない']::text[],ARRAY['Use this construction to express An adverb that indicates that the proposition expressed in the sentence is not always true.. An adverb that indicates that the proposition expressed in the sentence is not always true.']::text[],ARRAY['【Related Expression: いつもは~ない; みんなは~ない; 全ては~ない; 全部は~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"頭のいい人が、必ずしも成功するとは限らない。","japanese_furigana":"頭のいい人が、必ずしも成功するとは限らない。","english":"A bright person does not always succeed."},{"japanese":"高い料理が必ずしも美味しいわけではない。","japanese_furigana":"高い料理が必ずしも美味しいわけではない。","english":"Expensive dishes are not always delicious."}]'::jsonb),
    ('a164da07-a5fb-49cd-899b-b3bea2d52cb1'::uuid,ARRAY['Canonical pattern: 思えば']::text[],ARRAY['Use this construction to express An adverb that indicates feelings of nostalgia or regret when recollecting one’s past experiences.. An adverb that indicates feelings of nostalgia or regret when recollecting one’s past experiences.']::text[],ARRAY['The core sense is An adverb that indicates feelings of nostalgia or regret when recollecting one’s past experiences.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"思えば、大学時代はとても楽しかった。","japanese_furigana":"思えば、大学時代はとても楽しかった。","english":"When I come to think of it, I had a great time when I was in college."},{"japanese":"思えば、あの頃私は彼と政治問題について毎日のように議論したものだ。","japanese_furigana":"思えば、あの頃私は彼と政治問題について毎日のように議論したものだ。","english":"When I think back, I discussed political issues with him almost every day."}]'::jsonb),
    ('aed3a6ac-1ae0-4b11-8a9c-7fbc3a7ef4ba'::uuid,ARRAY['(i) {V/Adjective い}informal ように 思われる']::text[],ARRAY['Use this construction to express A verb that indicates what the speaker/writer feels spontaneously or his/her hesitation about asserting himself/herself.. A verb that indicates what the speaker/writer feels spontaneously or his/her hesitation about asserting himself/herself.']::text[],ARRAY['The core sense is A verb that indicates what the speaker/writer feels spontaneously or his/her hesitation about asserting himself/herself.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"来年の景気は今年よりもいいように思われる。","japanese_furigana":"来年の景気は今年よりもいいように思われる。","english":"It seems that the business conditions of the coming year will be better than those of this year."},{"japanese":"この病気の治療は約一か月かかると思われる。","japanese_furigana":"この病気の治療は約一か月かかると思われる。","english":"It appears that the treatment of this disease will take approximately one month."}]'::jsonb),
    ('6df780ff-b06c-4a28-8b4a-f2752067e63a'::uuid,ARRAY['(i) Nounの 折 ( に )']::text[],ARRAY['Use this construction to express A noun indicating special/uncommon and primarily desirable occasions which someone takes advantage of, or where someone is expected to do something or where something desirable takes place.. A noun indicating special/uncommon and primarily desirable occasions which someone takes advantage of, or where someone is expected to do something or where something desirable takes place.']::text[],ARRAY['【Related Expression: 時; さい; (せつ)に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"上京の折(に)はぜひお立ち寄り下さい。","japanese_furigana":"上京の折(に)はぜひお立ち寄り下さい。","english":"When you come up to Tokyo, please be sure to stop by."},{"japanese":"この前日本に帰った折(に)高校時代の友達に会った。","japanese_furigana":"この前日本に帰った折(に)高校時代の友達に会った。","english":"When I returned to Japan last time, I met with my high school friends."}]'::jsonb),
    ('25e8992d-8b48-4179-817f-d8942f7bc7ee'::uuid,ARRAY['(i) {Noun(の)/Adjectiveなstem(な)} 故 ( に )']::text[],ARRAY['Use this construction to express A conjunction that presents a reason or a cause.. A conjunction that presents a reason or a cause.']::text[],ARRAY['【Related Expression: (為)に; から; ので; だから; 従って】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女はその美貌(の)故(に)、悩みも多い。","japanese_furigana":"彼女はその美貌(の)故(に)、悩みも多い。","english":"Because of her good looks, she also has many things to worry about."},{"japanese":"結果にこだわりすぎる(が)故(に)、小さなことに心を奪われることになる。","japanese_furigana":"結果にこだわりすぎる(が)故(に)、小さなことに心を奪われることになる。","english":"Because you want the end result to be perfect, you end up being distracted by little things."}]'::jsonb),
    ('1b93cdf3-ade3-4d90-a15f-3470e0c8f48b'::uuid,ARRAY['(i) 更に Adjective(い/な)']::text[],ARRAY['Use this construction to express An adverb/conjunction that represents the idea of “additionally” or “further”.. An adverb/conjunction that represents the idea of “additionally” or “further”.']::text[],ARRAY['【Related Expression: 一緒; なお; もっと; より; あと; もう; その上; ひいては; 且つ; なお】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"更に大きいハリケーンがテキサス南部を襲った。","japanese_furigana":"更に大きいハリケーンがテキサス南部を襲った。","english":"An even larger hurricane struck South Texas."},{"japanese":"前の翻訳も難しかったが今度のは更に難しい。","japanese_furigana":"前の翻訳も難しかったが今度のは更に難しい。","english":"The last translation (job) was difficult, but this one is even harder."}]'::jsonb),
    ('7f0192bf-77a5-4490-9758-2d2436dc03be'::uuid,ARRAY['(i) Nounの 末 ( に )']::text[],ARRAY['Use this construction to express A noun that indicates the end of a period or the time after long, hard mental or physical work.. A noun that indicates the end of a period or the time after long, hard mental or physical work.']::text[],ARRAY['【Related Expression: あと(で); のち(に); あげく(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"さんざん迷った末に、友達の結婚祝いはコーヒーカップのセットを贈ることにした。","japanese_furigana":"さんざん迷った末に、友達の結婚祝いはコーヒーカップのセットを贈ることにした。","english":"After much hesitation, I decided to give my friends a set of coffee cups as a wedding present."},{"japanese":"試行錯誤の末(に)、やっと車に使える燃料電池ができた。","japanese_furigana":"試行錯誤の末(に)、やっと車に使える燃料電池ができた。","english":"After much trial and error, we ﬁnally made a fuel cell battery that can be used in cars."}]'::jsonb),
    ('3a225932-df04-4a00-9d99-2f9b082fafa7'::uuid,ARRAY['(i) Noun (duration) 来']::text[],ARRAY['Use this construction to express During a certain amount of time (something has continued up until the moment of speech or something has never been like the current state).. During a certain amount of time (something has continued up until the moment of speech or something has never been like the current state).']::text[],ARRAY['【Related Expression: ぶり; 以来; かん; 前から】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"トムは二十年来日本語の勉強を続けている。","japanese_furigana":"トムは二十年来日本語の勉強を続けている。","english":"Tom has been studying Japanese for the past 20 years."},{"japanese":"今年の冬は五十年来の寒さだ。","japanese_furigana":"今年の冬は五十年来の寒さだ。","english":"This winter is the coldest one in 50 years."}]'::jsonb),
    ('48b89fe0-d287-4f7d-abe9-4b3cc07c9325'::uuid,ARRAY['(i) Vます 次第']::text[],ARRAY['Use this construction to express A conjunction/noun to express that an action indicated by a preceding verb or an action implied by a preceding noun is a prerequisite for another action.. A conjunction/noun to express that an action indicated by a preceding verb or an action implied by a preceding noun is a prerequisite for another action.']::text[],ARRAY['【Related Expression: による; たらすぐ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"大阪に着き次第、お電話を差し上げます。","japanese_furigana":"大阪に着き次第、お電話を差し上げます。","english":"As soon as I get to Osaka, I will call you."},{"japanese":"原稿は完成次第お送り致します。","japanese_furigana":"原稿は完成次第お送り致します。","english":"I will send my manuscripts as soon as they are completed."}]'::jsonb),
    ('140f2cce-0c4f-4e06-bacf-f79c5fa05451'::uuid,ARRAY['Noun of time 毎']::text[],ARRAY['Use this construction to express A prefix which means ‘every (unit of time)’.. A prefix which means ‘every (unit of time)’.']::text[],ARRAY['【Related Expression: ごとに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は毎日一マイル泳ぐ・泳ぎます。","japanese_furigana":"私は毎日一マイル泳ぐ・泳ぎます。","english":"I swim one mile every day."},{"japanese":"弘は毎晩道子に電話しているそうだ。","japanese_furigana":"弘は毎晩道子に電話しているそうだ。","english":"I heard that Hiroshi calls Michiko every evening."}]'::jsonb),
    ('2f917c34-9614-4cd0-a27d-eccf6fc679a7'::uuid,ARRAY['(i) Number(+Counter)で 済む']::text[],ARRAY['Use this construction to express A verb that means “to be finished; to do (in the sense of being enough)”.. A verb that means “to be finished; to do (in the sense of being enough)”.']::text[],ARRAY['【Related Expression: 済ませる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ちょっと顔を見せるだけで済むと思う。","japanese_furigana":"ちょっと顔を見せるだけで済むと思う。","english":"I think just showing up for a while will be enough."},{"japanese":"面接は20分で済んだ。","japanese_furigana":"面接は20分で済んだ。","english":"The interview took only 20 minutes."}]'::jsonb),
    ('a01b413b-33ea-4a35-94bd-f7da7b5b6a93'::uuid,ARRAY['(i) {Demonstrative/Quantifier} 点 ( で )']::text[],ARRAY['Use this construction to express A noun which expresses the idea of "a point of argument; a point of evaluation; a point of view".. A noun which expresses the idea of "a point of argument; a point of evaluation; a point of view".']::text[],ARRAY['【Related Expression: 面】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はそういう点でまだ大人とは言えない。","japanese_furigana":"彼はそういう点でまだ大人とは言えない。","english":"He is not (literally: cannot be called) an adult in that respect."},{"japanese":"使いやすさの点ではこの辞書はネルソンの漢英辞典に及ばない。","japanese_furigana":"使いやすさの点ではこの辞書はネルソンの漢英辞典に及ばない。","english":"This dictionary is no match for Nelson''s Japanese-English Character Dictionary in terms of ease of use."}]'::jsonb),
    ('0659d80a-69a6-4eb5-ae0d-e4a782083eb3'::uuid,ARRAY['(i) {V/Adjective い} informal ために']::text[],ARRAY['Use this construction to express A noun that indicates a benefit, a purpose, a reason or a cause.. A noun that indicates a benefit, a purpose, a reason or a cause.']::text[],ARRAY['【Related Expression: から3; に5; ので; のに2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"学生は試験のために勉強する・勉強します。","japanese_furigana":"学生は試験のために勉強する・勉強します。","english":"Students study in preparation for exams. / Students study because there are exams."},{"japanese":"私は日本のことを知るため（に）日本へ行く・行きます。","japanese_furigana":"私は日本のことを知るため（に）日本へ行く・行きます。","english":"I''ll go to Japan (in order) to learn about Japan."}]'::jsonb),
    ('fb3568a1-9f26-4024-9716-64e7b04d0c17'::uuid,ARRAY['(i) Nounの 由']::text[],ARRAY['Use this construction to express A dependent noun that marks the content of what the writer has learned.. A dependent noun that marks the content of what the writer has learned.']::text[],ARRAY['【Related Expression: とのこと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この度は本社営業部長にご栄転の由、誠におめでとう存じます。","japanese_furigana":"この度は本社営業部長にご栄転の由、誠におめでとう存じます。","english":"I heard of your promotion this time to manager of the headquarters'' sales department. Please accept my sincere congratulations."},{"japanese":"地球環境保護の国際会議が来年当市で開催される由(である)。","japanese_furigana":"地球環境保護の国際会議が来年当市で開催される由(である)。","english":"It is said that an international conference on global environmental protection will be held in this city next year."}]'::jsonb),
    ('fc274c5c-cade-49b1-b7f2-f2562fd383e0'::uuid,ARRAY['(i) Vinformal 甲斐 が{ある/ない}']::text[],ARRAY['Use this construction to express A dependent noun that means something is worth someone’s effort.. A dependent noun that means something is worth someone’s effort.']::text[],ARRAY['The core sense is A dependent noun that means something is worth someone’s effort.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"日本語をよく勉強したかいがあって、日本語関係の会社に就職することができた。","japanese_furigana":"日本語をよく勉強したかいがあって、日本語関係の会社に就職することができた。","english":"It was worth studying Japanese hard because (literally: and) I was able to get a Japan-related job."},{"japanese":"社員一同の努力のかいがあって一時低調だった会社も上向きになった。","japanese_furigana":"社員一同の努力のかいがあって一時低調だった会社も上向きになった。","english":"The combined efforts of the company employees paid off, and the company, which had been in a slump for a while, started improving."}]'::jsonb),
    ('024d19e9-da37-4695-9fc4-163d1036aeb8'::uuid,ARRAY['Canonical pattern: 知る']::text[],ARRAY['Use this construction to express Someone gets information from some outside source.. Someone gets information from some outside source.']::text[],ARRAY['【Related Expression: 分かる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:日本のことを知っていますか。 B:はい、知っています。/いいえ、知りません。","japanese_furigana":"A:日本のことを知っていますか。 B:はい、知っています。/いいえ、知りません。","english":"A: Do you know about Japan? B: Yes, I do. / No, I don''t."},{"japanese":"木下さんを知っていますか。","japanese_furigana":"木下さんを知っていますか。","english":"Do you know Mr. Kinoshita?"}]'::jsonb),
    ('4be29420-bdc9-48c0-879f-f93d9c3c87e4'::uuid,ARRAY['(i) Noun の結果']::text[],ARRAY['Use this construction to express A noun which expresses the idea "as a result of".. A noun which expresses the idea "as a result of".']::text[],ARRAY['The core sense is A noun which expresses the idea "as a result of".; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"投票の結果、その提案は反対多数で否決された。","japanese_furigana":"投票の結果、その提案は反対多数で否決された。","english":"As a result of the vote, the proposal was rejected by the majority''s opposition."},{"japanese":"妻と相談した結果、家を買うことにした。","japanese_furigana":"妻と相談した結果、家を買うことにした。","english":"After my wife and I discussed it, we decided to buy a house."}]'::jsonb),
    ('537092c8-76c2-43bd-9932-7f0fa8b80130'::uuid,ARRAY['Canonical pattern: 結構']::text[],ARRAY['Use this construction to express An adverb that indicates that something exceeds the speaker''s and/or hearer''s expectation to a considerable degree.. An adverb that indicates that something exceeds the speaker''s and/or hearer''s expectation to a considerable degree.']::text[],ARRAY['【Related Expression: 案外; いがいと; 割合】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ここの寿司は、結構美味しいね。","japanese_furigana":"ここの寿司は、結構美味しいね。","english":"The sushi in this place is quite good, isn''t it?"},{"japanese":"この車は古いんだけど、結構よく走りますよ。","japanese_furigana":"この車は古いんだけど、結構よく走りますよ。","english":"This car is old, but it runs quite well, you know."}]'::jsonb),
    ('316ba829-4271-480f-802f-6eb5f9cb22d7'::uuid,ARRAY['Canonical pattern: 聞こえる']::text[],ARRAY['Use this construction to express Something is passively and spontaneously audiable.. Something is passively and spontaneously audiable.']::text[],ARRAY['【Related Expression: 聞ける】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私（に）は鶯の声がよく聞こえる・聞こえます。","japanese_furigana":"私（に）は鶯の声がよく聞こえる・聞こえます。","english":"To me the cries of a nightingale are clearly audible. / I can clearly hear the cries of a nightingale."},{"japanese":"その音は小さ過ぎて聞こえない。","japanese_furigana":"その音は小さ過ぎて聞こえない。","english":"That sound is too weak and is not audible."}]'::jsonb),
    ('24dee30c-315e-4986-88a4-70aa79e47089'::uuid,ARRAY['(i) NounPhrase 自体']::text[],ARRAY['Use this construction to express A dependent noun that is used to emphasize the referent of the preceding noun.. A dependent noun that is used to emphasize the referent of the preceding noun.']::text[],ARRAY['【Related Expression: 自身; そのもの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"インターネット自体は情報の通路であって、内容は持たない。","japanese_furigana":"インターネット自体は情報の通路であって、内容は持たない。","english":"The Internet is a path for information and does not contain any content itself."},{"japanese":"私にとってはこの試合に出られること自体が光栄なことです。","japanese_furigana":"私にとってはこの試合に出られること自体が光栄なことです。","english":"For me, being able to participate in this match in and of itself is an honour."}]'::jsonb),
    ('f37d1af4-4fb1-4320-b73f-c44ca51fee19'::uuid,ARRAY['Canonical pattern: 自分（共感視点）']::text[],ARRAY['Use this construction to express A reflexive pronoun that refers (back) to a human subject with whom the speaker is empathising.. A reflexive pronoun that refers (back) to a human subject with whom the speaker is empathising.']::text[],ARRAY['【Related Expression: 自分2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"土田は幸子が自分を愛していることを知らなかった・知りませんでした。","japanese_furigana":"土田は幸子が自分を愛していることを知らなかった・知りませんでした。","english":"Tsuchida didn''t know that Sachiko loved him (literally: himself)."},{"japanese":"1:ゆかりは歩きながら考えていた。 2:健一は自分が本当に好きなんだろうか。","japanese_furigana":"1:ゆかりは歩きながら考えていた。 2:健一は自分が本当に好きなんだろうか。","english":"1: Yukari was walking while thinking. 2: Does Kenichi really love me (literally: myself)?"}]'::jsonb),
    ('00fafc0f-33c7-42d2-9071-880d684c5f0d'::uuid,ARRAY['Canonical pattern: 自分（対比）']::text[],ARRAY['Use this construction to express A reflexive pronoun that refers (back) to a human subject, the referent of which is contrasted with someone else.. A reflexive pronoun that refers (back) to a human subject, the referent of which is contrasted with someone else.']::text[],ARRAY['【Related Expression: 自分1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本人は自分の国の文化をユニークだと思っている・います。","japanese_furigana":"日本人は自分の国の文化をユニークだと思っている・います。","english":"The Japanese think that their country''s culture is unique."},{"japanese":"メアリーは自分で何でもする・します。","japanese_furigana":"メアリーは自分で何でもする・します。","english":"Mary does everything by herself."}]'::jsonb),
    ('0fec0d16-aa16-4efa-b358-e25ae1445183'::uuid,ARRAY['Canonical pattern: 要る']::text[],ARRAY['Use this construction to express Someone, something needs something. Someone, something needs something']::text[],ARRAY['The core sense is Someone, something needs something; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"君達は英和辞典が要る・要ります。","japanese_furigana":"君達は英和辞典が要る・要ります。","english":"You need an English-Japanese dictionary."},{"japanese":"私は今お金が要る。","japanese_furigana":"私は今お金が要る。","english":"I need money now."}]'::jsonb),
    ('c6386e1f-7c54-4bba-8733-57001e003d10'::uuid,ARRAY['Canonical pattern: 見える']::text[],ARRAY['Use this construction to express Someone or something is passively/spontaneously visible.. Someone or something is passively/spontaneously visible.']::text[],ARRAY['【Related Expression: 見られる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私（に）は遠くの物がよく見える・見えます。","japanese_furigana":"私（に）は遠くの物がよく見える・見えます。","english":"To me distant objects are very visible."},{"japanese":"窓から（は）海が見える・見えます。","japanese_furigana":"窓から（は）海が見える・見えます。","english":"From the window the ocean is visible."}]'::jsonb),
    ('ee59f20f-43ee-4feb-ab47-74ef94f67a1c'::uuid,ARRAY['言わば Sentence。']::text[],ARRAY['Use this construction to express An adverb that means “if I were to say it some way (or a different way)”.. An adverb that means “if I were to say it some way (or a different way)”.']::text[],ARRAY['【Related Expression: 言ってみれば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この本は、言わば私のバイブルだ。","japanese_furigana":"この本は、言わば私のバイブルだ。","english":"This is, as it were, my Bible."},{"japanese":"この試験は言わばアメリカの大学に留学する際のTOEFLに当たる。","japanese_furigana":"この試験は言わばアメリカの大学に留学する際のTOEFLに当たる。","english":"This test is, so to speak, the equivalent of the TOEFL, which people take when they (want to) study at a university in the U.S."}]'::jsonb),
    ('ea9bb6cb-1dc7-41c8-8e5a-2adbc70b1d5d'::uuid,ARRAY['Canonical pattern: 逆に']::text[],ARRAY['Use this construction to express An adverb to introduce an event which takes place contrary to one''s expectation/intention, or an action or event which is converse to that stated in the preceding sentence or clause.. An adverb to introduce an event which takes place contrary to one''s expectation/intention, or an action or event which is converse to that stated in the preceding sentence or clause.']::text[],ARRAY['【Related Expression: かえって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"薬を飲んだら、逆に熱が出た。","japanese_furigana":"薬を飲んだら、逆に熱が出た。","english":"Contrary to expectations, when I took medicine, I got a fever."},{"japanese":"叱られると思ったのに、逆にほめられた。","japanese_furigana":"叱られると思ったのに、逆にほめられた。","english":"I expected to be scolded but, contrary to my expectation, I was praised."}]'::jsonb),
    ('26178254-75be-4a79-8188-a9854e515a6b'::uuid,ARRAY['(i) Vinformal past 途端 ( に )']::text[],ARRAY['Use this construction to express A noun/adverb which expresses the idea that ''something occurred the moment someone did something or something took place''.. A noun/adverb which expresses the idea that ''something occurred the moment someone did something or something took place''.']::text[],ARRAY['【Related Expression: と同時に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"先生の顔を見た途端（に）宿題があったことを思い出した。","japanese_furigana":"先生の顔を見た途端（に）宿題があったことを思い出した。","english":"The moment I saw my teacher, I remembered that there was a homework assignment."},{"japanese":"ドアを開けたら、途端にカレーの匂いがした。","japanese_furigana":"ドアを開けたら、途端にカレーの匂いがした。","english":"The moment I opened the door, I smelled curry."}]'::jsonb),
    ('4ad19909-6c29-4d06-825c-b178a2419682'::uuid,ARRAY['(i) Noun の通り(に)']::text[],ARRAY['Use this construction to express A dependent noun which expresses the idea that someone does something or something takes place in the same way as something else.. A dependent noun which expresses the idea that someone does something or something takes place in the same way as something else.']::text[],ARRAY['【Related Expression: ように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"説明書の通り（に）やったが、うまくいかなかった。","japanese_furigana":"説明書の通り（に）やったが、うまくいかなかった。","english":"I did it as the manual shows (literally: in the same way as the manual), but it didn''t work."},{"japanese":"私の言う通り（に）体を動かして下さい。","japanese_furigana":"私の言う通り（に）体を動かして下さい。","english":"Please move your body as I tell you to (literally: in the same way as I tell you)."}]'::jsonb),
    ('c6dd4e4e-fd9c-4937-a2f5-951c76eff013'::uuid,ARRAY['(i) Vinformal 際 ( に )']::text[],ARRAY['Use this construction to express On the special occasion of/when.. On the special occasion of/when.']::text[],ARRAY['【Related Expression: 場合; にあったって/あたり; おりに; 時に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"詳しいことは八月に上京する際に、お話し致します。","japanese_furigana":"詳しいことは八月に上京する際に、お話し致します。","english":"I will tell you the details when I come down to Tokyo in August."},{"japanese":"これは大学卒業の際に父が買ってくれたワープロです。","japanese_furigana":"これは大学卒業の際に父が買ってくれたワープロです。","english":"This is a word processor which my father bought me on the occasion of my college graduation."}]'::jsonb),
    ('1329e30b-6bbd-412a-82b5-f40a414b1517'::uuid,ARRAY['(i) おVます 願います']::text[],ARRAY['Use this construction to express A verb that expresses a polite request.. A verb that expresses a polite request.']::text[],ARRAY['【Related Expression: Verb て下さい; をVerb ます下さい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"初めに、これだけは必ずお読み願います。","japanese_furigana":"初めに、これだけは必ずお読み願います。","english":"Please be sure to read at least this (part) first."},{"japanese":"禁煙にご協力願います。","japanese_furigana":"禁煙にご協力願います。","english":"Thank you for not smoking (literally: Please cooperate with us in non-smoking)."}]'::jsonb),
    ('14a8f8e8-dd8c-4666-840a-11517e8586cb'::uuid,ARRAY['(i) {Noun/こんな/そんな/あんな/どんな} 風に Like {Noun/this/that/that ~ over there}, in what manner?']::text[],ARRAY['Use this construction to express With an appearance/style/tone/manner of ~.. With an appearance/style/tone/manner of ~.']::text[],ARRAY['【Related Expression: ように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私の家の庭は日本風に大きい石が置いてあります。","japanese_furigana":"私の家の庭は日本風に大きい石が置いてあります。","english":"The yard of my house has big rocks arranged in Japanese style."},{"japanese":"あんな風に勉強していたらいい成績は取れないだろう。","japanese_furigana":"あんな風に勉強していたらいい成績は取れないだろう。","english":"If he studies like that, he won''t get good grades."}]'::jsonb)
)
update public.japanese_grammar_guides g
set formation=case when coalesce(array_length(g.formation,1),0)=0 then e.formation_value else g.formation end,
    usage=case when coalesce(array_length(g.usage,1),0)=0 then e.usage_value else g.usage end,
    nuance=case when coalesce(array_length(g.nuance,1),0)=0 then e.nuance_value else g.nuance end,
    reference_examples=case when jsonb_typeof(coalesce(g.reference_examples,'[]'::jsonb))='array' and jsonb_array_length(coalesce(g.reference_examples,'[]'::jsonb))=0 then e.examples_value else g.reference_examples end,
    updated_at=now()
from enrichment e
where g.id=e.grammar_id and g.user_id=(select user_id from private.app_owner);

commit;
